gap_text='''# BT1803 W(E6) orbit-classification handoff
# Load GRAPE/nauty in GAP, construct the Schlaefli graph SRG(27,16,10,8),
# compute Aut(Schlaefli) (expected order 51840 = W(E6)), then compute orbits
# on 18-subsets of the 45 tritangent support lines containing the BT1795 image.
# The BT1795 image support indices are:
BT1795Image := [5,7,10,12,15,18,20,22,29,30,34,36,37,38,40,41,42,44];
# Required outputs:
# Size(AutSchlaefli);
# Orbit(AutSchlaefliOnTritangents, BT1795Image, OnSets);
# Stabilizer(AutSchlaefliOnTritangents, BT1795Image, OnSets);
# Orbit representatives grouped by old/new count, double-six syndrome ranks.
'''

return f'''#include <bits/stdc++.h>
using namespace std;
static const unsigned long long R[40][26]={{
{R}
}};
int main(int argc,char**argv){{
 int m=atoi(argv[1]); map<int,unsigned long long> cnt; unsigned long long total=0;
 vector<int> c(m); for(int i=0;i<m;i++)c[i]=i; unsigned long long w[26]={{0}};
 for(int a=0;a<m;a++)for(int k=0;k<26;k++)w[k]^=R[c[a]][k];
 while(true){{
 int wt=0; for(int k=0;k<26;k++)wt+=__builtin_popcountll(w[k]); cnt[wt]++; total++;
 int i=m-1; while(i>=0 && c[i]==40-m+i)i--; if(i<0)break;
 for(int j=i;j<m;j++)for(int k=0;k<26;k++)w[k]^=R[c[j]][k];
 c[i]++; for(int j=i+1;j<m;j++)c[j]=c[j-1]+1;
 for(int j=i;j<m;j++)for(int k=0;k<26;k++)w[k]^=R[c[j]][k];
 }}
 cerr<<"total "<<total<<"\n"; for(auto &kv:cnt)cout<<kv.first<<" "<<kv.second<<"\n";
}}
'''
